fun base exponent =>
  (if pre base exponent = true then
      have __do_jp := fun y =>
        have result := 1;
        do
        let r ←
          forIn (List.range exponent.toNat) result fun x r =>
              have result := r;
              have result := result * base;
              do
              pure PUnit.unit
              pure (ForInStep.yield result)
        have result : Int := r
        pure (Except.ok result);
      if (exponent == 0) = true then pure (Except.ok 1)
      else do
        let y ← pure PUnit.unit
        __do_jp y
    else pure (Except.error (errorMsg base exponent))).run

